//! Entries slice 31 — Batch 246 (Plan 250 / Research 278): the prism fork
//! delta, the serving state-cache family's FORK face — one own `rust_perf`
//! rule from PrismML-Eng/llama.cpp @ 5ae2e169eac202d2f065606539c3ad6ab8b51333
//! (#354, MIT, 2026-10-15; read at the vendor clone).
//!
//! - `seq-fork-carries-pending-rollback-record` — a sequence-fork (`seq_cp`)
//!   must carry PENDING mutation records, not just committed state: the
//!   deferred rollback recorded in `rs_idx` IS part of the sequence's state;
//!   for snapshot-plane state the copy takes the plane the rollback points
//!   to, never the live plane.

use crate::domains::rust_perf::PerfRule;

pub fn entries() -> Vec<PerfRule> {
    vec![
        PerfRule {
            rule_id: "seq-fork-carries-pending-rollback-record".to_string(),
            name: "A sequence-fork (seq_cp) must carry PENDING mutation records, not just committed state: a deferred rollback recorded in a per-sequence index (rs_idx) and applied at the next decode is part of the sequence's state — a fork that shares the cell but not the record makes the copy 'read the state from before the rollback'; for snapshot-plane state the fix copies the record AND the plane it points to ('Copy the snapshot plane that the pending rollback points to into the current plane of the destination'), never the live current plane; and the planes the snapshot system needs are sized at allocation (n_stream * (1 + n_rs_seq) planes), in size_t arithmetic".to_string(),
            category: "caching".to_string(),
            buggy_code: "// NAIVE: seq_cp shares the cell and the tail but NOT the pending\n// rollback record — a fork taken right after a rollback starts from\n// the PRE-rollback state.\n\n#[derive(Clone)]\npub struct Seq {\n    pub tail: Vec<u8>,      // committed state\n    pub rs_idx: usize,      // 0 = no pending rollback; else the snapshot row\n}\n\npub struct RecurrentMemory {\n    pub seqs: Vec<Seq>,\n    pub n_rs_seq: usize, // rollback snapshot slots per sequence\n}\n\nimpl RecurrentMemory {\n    // a partial seq_rm DEFERS: it records the rollback in rs_idx and the\n    // next decode applies it.\n    pub fn seq_rm(&mut self, seq: usize, _pos: usize) {\n        // ... record the pending rollback (deferred application)\n        self.seqs[seq].rs_idx = 1; // snapshot row 1 holds the pre-pos state\n    }\n\n    // THE DEFECT: the copy shares the cell (tail) but resets rs_idx —\n    // the destination starts from the UN-rolled-back state.\n    pub fn seq_cp(&mut self, src: usize, dst: usize) {\n        if src == dst {\n            return;\n        }\n        self.seqs[dst] = self.seqs[src].clone();\n        self.seqs[dst].rs_idx = 0; // pending rollback LOST on the fork\n    }\n\n    // the next decode applies a pending rollback — or would, if the\n    // fork had kept it\n    pub fn effective_state(&self, seq: usize) -> &[u8] {\n        &self.seqs[seq].tail // rs_idx == 0: the pre-rollback bytes serve\n    }\n}".to_string(),
            fixed_code: "// OPT: the pending rollback record is PART of the sequence's state —\n// the fork copies it; for snapshot-plane state the copy takes the\n// SNAPSHOT plane the record points to, never the live plane; and the\n// planes are counted at allocation.\n\n#[derive(Clone)]\npub struct Seq {\n    pub tail: Vec<u8>,\n    pub rs_idx: usize,\n}\n\npub struct RecurrentMemory {\n    pub seqs: Vec<Seq>,\n    pub n_rs_seq: usize,\n    // snapshot-plane store: n_stream * (1 + n_rs_seq) planes, sized in\n    // size_t arithmetic (the u32 product overflows first)\n    pub planes: Vec<Vec<u8>>,\n    pub n_stream: usize,\n}\n\nimpl RecurrentMemory {\n    pub fn seq_rm(&mut self, seq: usize, _pos: usize) {\n        self.seqs[seq].rs_idx = 1;\n        self.planes[seq] = self.seqs[seq].tail.clone(); // the snapshot row\n    }\n\n    pub fn seq_cp(&mut self, src: usize, dst: usize) {\n        if src == dst {\n            return;\n        }\n        // 'a pending partial rollback is applied at the next decode, so\n        // the copy must use the same snapshot row' — copy the RECORD\n        self.seqs[dst] = self.seqs[src].clone();\n        self.seqs[dst].rs_idx = self.seqs[src].rs_idx;\n        // snapshot-plane state: 'Copy the snapshot plane that the pending\n        // rollback points to into the current plane of the destination'\n        // — the live current plane of the source is PRE-rollback\n        if self.seqs[src].rs_idx != 0 {\n            let plane = src * (1 + self.n_rs_seq) + self.seqs[src].rs_idx;\n            self.seqs[dst].tail = self.planes[plane].clone();\n        }\n    }\n\n    // plane-count sizing: every stream carries its own rollback planes\n    pub fn plane_count(&self) -> usize {\n        self.n_stream * (1 + self.n_rs_seq)\n    }\n\n    pub fn effective_state(&self, seq: usize) -> &[u8] {\n        &self.seqs[seq].tail\n    }\n}\n\n// 'Add a test case that forks a sequence with a pending rollback and\n// compares its state with a sequence that rolled back directly.'\n#[test]\nfn fork_with_pending_rollback_matches_direct_rollback() {\n    let mut mem = RecurrentMemory {\n        seqs: vec![Seq { tail: vec![1, 2, 3, 4], rs_idx: 0 }, Seq { tail: vec![], rs_idx: 0 }],\n        n_rs_seq: 8,\n        planes: vec![vec![]; 2 * 9],\n        n_stream: 2,\n    };\n    // seq 0 rolls back 3 tokens (deferred): the snapshot plane is taken\n    mem.seq_rm(0, 9); // pos 9 of a 12-token prompt\n    // FORK seq 0 -> seq 1 while the rollback is pending\n    mem.seq_cp(0, 1);\n    // the reference: seq 0's rollback applied directly\n    let direct: Vec<u8> = mem.planes[0 * 9 + 1].clone();\n    // 'The fork must match it bitwise' — the fork carries the record AND\n    // the snapshot plane, so its effective state IS the rolled-back one\n    assert_eq!(mem.effective_state(1), direct.as_slice());\n    assert_eq!(mem.seqs[1].rs_idx, 1); // the record survived the fork\n}".to_string(),
            context_notes: Some("Grade B+ — NotBenchable decision content (a serving state-fork correctness contract; the failure is wrong logits on a forked serving sequence, not a Rust-side timing axis). SOURCE (PrismML-Eng/llama.cpp #354 'memory : keep a pending rollback across seq_cp, and default MTP draft depth to 2 on CUDA' @ 5ae2e169eac202d2f065606539c3ad6ab8b51333, MIT, 2026-10-15, bri-prism; the fork's serving lineage; diff read in full at the vendor clone E:/git/vendor/prismml-llama.cpp, every quote verified verbatim AT CONVERSION). THE DEFECT (commit message, verbatim): 'With n_rs_seq != 0, a partial seq_rm records the rollback in rs_idx and the next decode applies it. seq_cp shared the cell but not rs_idx, so a sequence forked right after a rollback read the state from before the rollback.' THE REPAIR, FACE 1 — the recurrent record (src/llama-memory-recurrent.cpp seq_cp, the added lines): 'a pending partial rollback is applied at the next decode, so the copy must use the same snapshot row' — 'if (n_rs_seq != 0 && (uint32_t) seq_id_src < rs_idx.size() && (uint32_t) seq_id_dst < rs_idx.size()) { rs_idx[seq_id_dst] = rs_idx[seq_id_src]; }'. THE REPAIR, FACE 2 — the snapshot plane (commit message, verbatim): 'The DSV4 compressor state had the same problem: seq_cp copied the current state plane of the source and reset rs_idx of the destination. Copy the snapshot plane that the pending rollback points to into the current plane of the destination instead.' — the code (src/llama-kv-cache-dsv4.cpp seq_cp, verbatim comment): '// copy the snapshot plane of a pending rollback, so the destination starts from the rolled-back state' with 'sc_info.ssrc.push_back(rs_src*n_stream + (uint32_t) seq_id_src);' — the PLANE ADDRESS is rs_src*n_stream + seq (the plane store is indexed by rollback slot first), and the destination's CURRENT plane receives the source's SNAPSHOT plane (never the source's live plane: that one is pre-rollback). THE REPAIR, FACE 3 — the plane-count sizing (the same file, the constructor): the context allocation now counts every stream's rollback planes — 'size_t(2)*(1 + size_t(n_stream)*(1 + n_rs_seq))*hparams.n_layer()*ggml_tensor_overhead()' (was 'size_t(2u*(1 + n_stream)*...)' — the u32 arithmetic overflows first and the plane views now iterate 'for (uint32_t s = 0; s < n_planes; ++s)' over n_planes = n_stream*(1 + n_rs_seq), the planes the snapshot system actually addresses). THE GATE (commit message, verbatim): 'Add a test case that forks a sequence with a pending rollback and compares its state with a sequence that rolled back directly.' — the test header adds: 'Fork a sequence with seq_cp while its partial rollback is pending, then decode one token on the fork. The reference rolls back seq 1 directly. The fork must match it bitwise.' + 'The tiny test weights make the recurrent part too small to show in the logits, so compare the state bytes.' — the ORACLE is state-byte equality against a direct rollback, bypassing logits entirely (the honest instrument for a state defect the forward pass can mask). KINSHIP (do not double-count): the serving state-cache family's FIFTH face — prompt-cache-canonical-interval-keys + prompt-cache-rewind-states-min-gap-eviction (entries_21, B219) own KEYING and EVICTION; partial-state-serialization-honors-rollback-contract-at-leaf-cache (entries_27, B239) owns WHAT a partial write owes (partial state = what rollback cannot undo — THIS owns what a COPY owes while a rollback is still PENDING: the two compose, a fork of a partially-serialized lane keeps both halves); cache-write-admission-requires-restoring-consumer (entries_27, B239) owns ADMISSION; reuse-admission-threshold-must-equal-window-semantics (entries_28, B241) owns REUSE acceptance; empty-slot-first-victim-order-save-before-overwrite (entries_28, B241) owns victim order + overwrite persistence (its save-before-overwrite is the WRITE-time twin of THIS's copy-time law — both say a state someone will read must not be silently regressed); THIS owns the FORK/COPY axis: pending mutations travel WITH the fork. append-cache-rewind-overwrite-in-place (kernel_opt entries_gpu_05) owns the rewind MECHANISM (pointer rollback over a ring); mid-prefill-recurrent-state-capture-boundary-unsplit (kernel_opt entries_gpu_08, B236) owns capture placement inside a command — both mechanism/placement, not copy semantics. tree-verify-recurrent-state-parent-reload (entries_gpu_07, B77) reloads a parent's stored state at a branch — the SPECULATIVE twin of this law (a fork reads its parent's post-rollback state; there the reload is the mechanism, here the copy is). NOVEL (grep seq_cp|pending rollback|rs_idx|snapshot plane|fork.{0,20}rollback over rust_perf + kernel_opt corpora at claim: ZERO hits — no rule owns fork/copy propagation of deferred mutations; the deferred/pending axis itself is new to the family). REGIME: serving state stores with DEFERRED mutations (rollback-on-next-decode rings, write-behind indices, snapshot-plus-current plane pairs) exposed to a fork/branch operation (sequence forking, task spawning, snapshot copy) — anywhere a copy could race a pending write. ANTI-REGIME: mutations applied eagerly at seq_rm time (nothing pending to carry — the record is always 0); copies that snapshot the WHOLE store atomically (no per-sequence records to miss); single-sequence stores (no fork exists). The MTP-depth half of the commit rides cost-aware-verify-length-survival-cost-table (entries_gpu_86) as a count-neutral rider — different family, different rule. Cite: @ 5ae2e169eac202d2f065606539c3ad6ab8b51333 — src/llama-memory-recurrent.cpp seq_cp (+4 lines, the rs_idx copy + comment), src/llama-kv-cache-dsv4.cpp:920-924 (the size_t plane-count constructor) + :971-975 (n_planes views) + :1022-1036 (seq_cp's snapshot-plane ssrc + comment) + :1517-1531 (the rs_src resolution at the cache level), src/llama-kv-cache-dsv4.h:27-30 (the seq_cp signature), tests/test-recurrent-state-rollback.cpp:207-272 (test_seq_cp_pending_rollback, the bitwise fork-vs-direct oracle), common/arg.cpp:4103-4117 + common/common.cpp:1431-1466 + common/common.h:321-334 (the MTP depth-2-on-CUDA half, cited by the rider), commit message (all quotes); Batch 246 / Plan 250 / Research 278.".to_string()),
            // Not benchable: a state-fork correctness contract — the win is
            // fork-serves-the-rolled-back-state, not a Rust-side A/B axis.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
